rows=[]
for case in cases:
    h,w=case['height'],case['width']
    visible=torch.zeros(2,h,w,dtype=torch.bool)
    visible[:,10:h-10,10:w-10]=True
    y0,x0,y1,x1=case['erase']
    visible[:,y0:y1,x0:x1]=False
    counts=geometric_counts(visible,case['flip'],case['dy'],case['dx'])
    assert torch.equal(counts[0],counts[1])
    indices=counts[0].nonzero()
    mass=sorted((int(p),int(q),int(counts[0,p,q])) for p,q in indices)
    digest=hashlib.sha256(json.dumps(mass).encode()).hexdigest()
    assert digest==case['mass_sha256'],case
    row_mass=counts.sum(-1)
    col_mass=counts.sum(-2)
    assert int(row_mass[0].count_nonzero())==case['supported_rows']
    assert int(col_mass[0].count_nonzero())==case['supported_columns']
    assert int(counts[0].sum())==case['overlap_pixels']
    valid_rows=row_mass>0
    # Select existing support rather than inventing mass for empty rows/columns.
    targets=counts.to(torch.float32)
    targets[valid_rows]=targets[valid_rows]/row_mass[valid_rows,None]
    assert bool(torch.isfinite(targets).all())
    assert torch.allclose(targets.sum(-1)[valid_rows],torch.ones_like(targets.sum(-1)[valid_rows]),atol=1e-7,rtol=1e-7)
    assert bool((targets[~valid_rows]==0).all())
    rows.append({'height':h,'width':w,'flip':case['flip'],'dy':case['dy'],'dx':case['dx'],'erase':case['erase'],'exact_mass_sha256':digest})
print(json.dumps({'status':'TORCH_COUNTS_EXACT_WITH_INDEPENDENT_PIXEL_AND_RECTANGLE_REFERENCES','at':datetime.now().astimezone().isoformat(),'cases':len(rows),'batch_fixture':2,'tensor_math_device':'cpu','new_production_NN':0,'optimizer_updates':0,'model_calls':0,'rows':rows,'boundary':'CPU integer geometry tensor/soft-target support only; no real loader/RNG/model/gradient/M0/retrieval validation. No source mutation, GPU/temperature/power/25 query or package install.'}))
